-// The order in which an item's batches are used up.
+// The order in which an item's batches are used up: FEFO, no expiry last, then
+// received first, then lower id (docs/DATA.md).
 function consumptionOrder(batches) {
-  return [...batches].sort((a, b) => b.receivedOn.localeCompare(a.receivedOn));
+  const NO_EXPIRY = "9999-99-99"; // sorts after every real date
+  return [...batches].sort(
+    (a, b) =>
+      (a.expires ?? NO_EXPIRY).localeCompare(b.expires ?? NO_EXPIRY) ||
+      a.receivedOn.localeCompare(b.receivedOn) ||
+      a.id - b.id,
+  );
 }

